body {
	margin: 0;
	font-family: sans-serif;
	color: #2b2620;
	background: #fbf8f1;
}

.shell.mk-17s9si0 {
				min-height: 100vh;
				display: flex;
				flex-direction: column;
			}
			.bar.mk-17s9si0 {
				position: sticky;
				top: 0;
				display: flex;
				align-items: center;
				justify-content: space-between;
				gap: 12px;
				padding: 12px 20px;
				border-bottom: 1px solid #e4ddd0;
				background: #fbf8f1;
			}
			.brand.mk-17s9si0 {
				font-size: 20px;
				font-weight: 600;
			}
			.pill.mk-17s9si0 {
				display: inline-flex;
				align-items: center;
				justify-content: center;
				min-height: 44px;
				padding: 10px 18px;
				border: 1px solid #2f6f5e;
				border-radius: 999px;
				background: #2f6f5e;
				color: #ffffff;
				font: inherit;
				font-weight: 600;
			}
			.pill.mk-17s9si0:active {
				transform: scale(0.97);
				opacity: 0.85;
			}
			.content.mk-17s9si0 {
				padding: 20px;
			}
